import React, { useEffect, useState } from "react";
import axios from "axios";

function Packets() {
  const [packets, setPackets] = useState([]);

  useEffect(() => {
    fetchPackets();
  }, []);

  const fetchPackets = async () => {
    try {
      const token = localStorage.getItem("access_token");

      const res = await axios.get(
        "http://127.0.0.1:8000/packets/live",
        {
          headers: {
            Authorization: `Bearer ${token}`,
          },
        }
      );

      console.log(res.data);

      // IMPORTANT FIX
      setPackets(res.data.packets);

    } catch (error) {
      console.error(error);
    }
  };

  return (
    <div style={styles.container}>
      <h1>Network Packet Monitoring</h1>

      {packets.length === 0 ? (
        <p>No packets found</p>
      ) : (
        packets.map((packet, index) => (
          <div key={index} style={styles.card}>
            <p><b>Source:</b> {packet.source_ip}</p>
            <p><b>Destination:</b> {packet.destination_ip}</p>
            <p><b>Protocol:</b> {packet.protocol}</p>
            <p><b>Packet Size:</b> {packet.packet_size}</p>
            <p><b>Risk Score:</b> {packet.risk_score}</p>
          </div>
        ))
      )}
    </div>
  );
}

const styles = {
  container: {
    padding: "30px",
    color: "white",
  },
  card: {
    background: "#1e293b",
    padding: "15px",
    marginTop: "15px",
    borderRadius: "8px",
  },
};

export default Packets;
